-- MANAGEMENT-PERSONAS-5 / QUALITY-IMPROVEMENT-AUDIT-1 (2026-10-26, pillar autonomy). Owner, 2026-10-26 08:53Z, verbatim: "REMEDIATE ALL FLEET
-- BREACHES AUTOMATICALLY AND PERMANENTLY. IDENTIFY AND AUDIT QUALITY METRIC CONTINUOUS IMPROVEMENT SYSTEMWIDE ACROSS THE FLEET."
-- Split with the self-remediation thread (BREACH-ONE-MEANING-1, PR 4444): that thread owns triggers, thresholds, cause mapping and breach
-- fixes; this migration owns the improvement audit (does each metric get better, and who moves it) and the lever reviews.
--
-- Audit, 2026-10-26 08:58Z, 270 enabled metric triggers: 146 on target; 62 in breach, of which 38 are worse than 7 days ago, 4 flat, 8
-- improving and 12 too new to compare; 62 unmeasured (56 BP26 catalogue metrics with a producer still to build, which the BP26 trigger
-- tracks, and 6 others). Every breach has an open METRIC-TRIGGER issue, but only 8 carry a code-task lever: filing works, the remedies do
-- not move the metrics, and nothing replaced a remedy that failed (METRIC-CLOSED-LOOP-1 says it is replaced, not repeated, after 7 days).
-- The share of registered metrics meeting target was 52% on 10-17 and 50% on 10-26: no improvement over 9 days.
--
-- WHAT THE MANAGERS' HOURLY TICK NOW ALSO DOES (fleet_tasks management-personas)
--   1. metric_improvement_now: per enabled trigger, the value now and 7 days ago (metric_history), a verdict (on-target, breach-improving,
--      breach-flat, breach-worsening, breach-new, unmeasured), its program, its cause_key (metric_breach_cause, PR 4444), whether its lever
--      has a code-task line, and its open METRIC-TRIGGER issue. metric_improvement_trend keeps one row per hour.
--   2. metrics metrics_worsening_7d (target 0), metrics_unmeasured (target 0) and fleet_quality_change_7d (the daily target: the quality
--      index, the share of measured triggers on target, must rise; non-negative over 7 days).
--   3. lever review: each breach that is worse or flat after 7 days gets one Cloudflare agent turn (at most every 3 days, 5 per tick) that
--      names why the metric does not move and a different lever (a code-task with an anchor, or a corrected target with evidence); the
--      answer is appended to the metric's open issue (persona_actions kind lever-review). An empty answer is not appended and is asked again.
--   4. one METRIC-UNMEASURED-1 issue per owner of an unmeasured non-BP26 metric, with a closing probe on metric_improvement_now; it closes
--      with evidence when every one of them holds a value.
--   5. the portfolio brief states the audit and the 7-day quality change.
--   Also: the earlier agent steps (root-cause diagnosis, parked-task re-plan) no longer append "(the model returned no text)" to issues;
--   a root-cause turn with an empty answer is asked again (qnfo-agents 0.3.0 fixes the empty answers at their source).
--
-- Stop the decisions without a deploy: INSERT OR REPLACE INTO ops_config (key, value) VALUES ('persona_actions', 'off');
-- Verify after apply:
--   SELECT verdict, COUNT(*) FROM metric_improvement_now GROUP BY verdict;
--   SELECT * FROM metric_improvement_trend ORDER BY tick DESC LIMIT 3;
--   SELECT * FROM persona_actions WHERE kind = 'lever-review' ORDER BY id DESC LIMIT 5;
--
-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261026_mp5_workflow
-- Rollback: UPDATE fleet_tasks SET definition = (SELECT definition FROM bak_20261026_mp5_workflow WHERE id = 'management-personas'), version = version + 1 WHERE id = 'management-personas'; DELETE FROM metric_registry WHERE metric IN ('metrics_worsening_7d', 'metrics_unmeasured', 'fleet_quality_change_7d'); DELETE FROM analytics_metric_triggers WHERE metric_key IN ('metrics_worsening_7d', 'fleet_quality_change_7d');

CREATE TABLE IF NOT EXISTS bak_20261026_mp5_workflow AS SELECT id, definition, version FROM fleet_tasks WHERE id = 'management-personas';

CREATE TABLE IF NOT EXISTS metric_improvement_now (
  trigger_id INTEGER PRIMARY KEY,
  metric_key TEXT NOT NULL,
  owner TEXT,
  program_code TEXT,
  operator TEXT,
  threshold REAL,
  val REAL,
  val_7d REAL,
  hit INTEGER,
  verdict TEXT NOT NULL,
  cause_key TEXT,
  has_code_task INTEGER,
  open_issue_id INTEGER,
  priority INTEGER,
  bp26 INTEGER,
  computed_at TEXT
);

CREATE TABLE IF NOT EXISTS metric_improvement_trend (
  tick TEXT PRIMARY KEY,
  triggers INTEGER,
  on_target INTEGER,
  improving INTEGER,
  flat INTEGER,
  worsening INTEGER,
  new_breach INTEGER,
  unmeasured INTEGER,
  quality_index REAL
);

DROP VIEW IF EXISTS v_metric_improvement_by_program;
CREATE VIEW v_metric_improvement_by_program AS
SELECT program_code, COUNT(*) AS triggers, SUM(verdict = 'on-target') AS on_target, SUM(verdict = 'breach-improving') AS improving,
  SUM(verdict = 'breach-flat') AS flat, SUM(verdict = 'breach-worsening') AS worsening, SUM(verdict = 'breach-new') AS new_breach,
  SUM(verdict = 'unmeasured') AS unmeasured, SUM(verdict LIKE 'breach-%' AND has_code_task = 0) AS breaches_without_code_lever,
  ROUND(100.0 * SUM(verdict = 'on-target') / MAX(1, SUM(verdict <> 'unmeasured')), 1) AS quality_index
FROM metric_improvement_now GROUP BY program_code;

-- Empty agent answers: never appended, and a root-cause turn is asked again (runs before the new steps are appended, which carry their own filter).
UPDATE fleet_tasks
SET definition = replace(replace(definition,
    'r.status IN (''done'', ''failed'', ''error'')',
    'r.status IN (''done'', ''failed'', ''error'') AND COALESCE(r.result, '''') NOT LIKE ''(the model returned no text)%'''),
    'WHERE r.instance = ''root-cause-'' || a.id)',
    'WHERE r.instance = ''root-cause-'' || a.id AND COALESCE(r.result, '''') NOT LIKE ''(the model returned no text)%'')'),
  version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
WHERE id = 'management-personas' AND instr(definition, 'NOT LIKE ''(the model returned no text)%''') = 0;

UPDATE agent_issues SET description = replace(description, '): (the model returned no text)', '): no answer yet; the managers ask again')
WHERE status = 'open' AND description LIKE '%): (the model returned no text)%';
UPDATE fleet_tasks
SET definition = json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(definition, '$.steps[#]', json('{"type": "sql", "name": "mi-clear", "db": "AUDIT", "sql": "DELETE FROM metric_improvement_now"}')), '$.steps[#]', json('{"type": "sql", "name": "mi-snapshot", "db": "AUDIT", "sql": "INSERT OR REPLACE INTO metric_improvement_now (trigger_id, metric_key, owner, program_code, operator, threshold, val, val_7d, hit, verdict, cause_key, has_code_task, open_issue_id, priority, bp26, computed_at)\nSELECT x.id, x.metric_key, x.owner, x.program_code, x.operator, x.threshold, x.v, x.v7, x.hit,\n CASE WHEN x.v IS NULL THEN ''unmeasured'' WHEN x.hit = 0 THEN ''on-target'' WHEN x.v7 IS NULL THEN ''breach-new''\n      WHEN (x.operator IN (''gt'', ''gte'') AND x.v < x.v7) OR (x.operator IN (''lt'', ''lte'') AND x.v > x.v7) THEN ''breach-improving''\n      WHEN x.v = x.v7 THEN ''breach-flat'' ELSE ''breach-worsening'' END,\n (SELECT c.cause_key FROM metric_breach_cause c WHERE c.metric_key = x.metric_key LIMIT 1),\n CASE WHEN x.action LIKE ''%code-task:%'' THEN 1 ELSE 0 END,\n (SELECT MIN(i.id) FROM agent_issues i WHERE i.status = ''open'' AND i.title LIKE ''METRIC-TRIGGER-'' || x.id || ''-%''),\n x.priority, x.bp26, strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'') FROM (SELECT t.id, t.metric_key, a.owner, a.operator, a.threshold, a.action, a.priority, t.hit,    CASE WHEN t.val IS NULL OR trim(CAST(t.val AS TEXT)) = '''' THEN NULL ELSE CAST(t.val AS REAL) END AS v,    (SELECT h.value FROM metric_history h WHERE h.metric = t.metric_key AND h.day <= date(''now'', ''-7 days'') AND h.day >= date(''now'', ''-10 days'') ORDER BY h.day DESC LIMIT 1) AS v7,    CASE WHEN a.owner LIKE ''program-manager:%'' THEN substr(a.owner, 17) ELSE COALESCE((SELECT s.program_code FROM service_program_map s WHERE s.service = a.owner LIMIT 1), ''QNFO.OPS'') END AS program_code,    CASE WHEN EXISTS (SELECT 1 FROM metric_registry r WHERE r.metric = t.metric_key AND r.source_of_truth LIKE ''%[BP26]%'') THEN 1 ELSE 0 END AS bp26  FROM v_metric_trigger_state t JOIN analytics_metric_triggers a ON a.id = t.id WHERE a.enabled = 1) x"}')), '$.steps[#]', json('{"type": "sql", "name": "mi-trend", "db": "AUDIT", "sql": "INSERT OR REPLACE INTO metric_improvement_trend (tick, triggers, on_target, improving, flat, worsening, new_breach, unmeasured, quality_index) SELECT strftime(''%Y-%m-%dT%H:00Z'', ''now''), COUNT(*), SUM(verdict = ''on-target''), SUM(verdict = ''breach-improving''), SUM(verdict = ''breach-flat''), SUM(verdict = ''breach-worsening''), SUM(verdict = ''breach-new''), SUM(verdict = ''unmeasured''), ROUND(100.0 * SUM(verdict = ''on-target'') / MAX(1, SUM(verdict <> ''unmeasured'')), 1) FROM metric_improvement_now"}')), '$.steps[#]', json('{"type": "sql", "name": "mi-metric-metrics_worsening_7d", "db": "AUDIT", "sql": "UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM metric_improvement_now WHERE verdict IN (''breach-worsening'', ''breach-flat'')) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), state = ''MEASURED'' WHERE metric = ''metrics_worsening_7d''"}')), '$.steps[#]', json('{"type": "sql", "name": "mi-metric-metrics_unmeasured", "db": "AUDIT", "sql": "UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM metric_improvement_now WHERE verdict = ''unmeasured'') AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), state = ''MEASURED'' WHERE metric = ''metrics_unmeasured''"}')), '$.steps[#]', json('{"type": "sql", "name": "mi-metric-fleet_quality_change_7d", "db": "AUDIT", "sql": "UPDATE metric_registry SET last_value = CAST((SELECT ROUND(n.quality_index - o.quality_index, 1) FROM metric_improvement_trend n, metric_improvement_trend o WHERE n.tick = (SELECT MAX(tick) FROM metric_improvement_trend) AND o.tick = (SELECT MIN(tick) FROM metric_improvement_trend WHERE tick >= strftime(''%Y-%m-%dT%H:00Z'', ''now'', ''-7 days''))) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), state = ''MEASURED'' WHERE metric = ''fleet_quality_change_7d''"}')), '$.steps[#]', json('{"type": "sql", "name": "mi-unmeasured-file", "db": "AUDIT", "sql": "INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''METRIC-UNMEASURED-1: '' || m.owner || '' has metrics with no value'', ''QUALITY-IMPROVEMENT-AUDIT-1 (managers, hourly): '' || COUNT(*) || '' enabled metric trigger(s) owned by '' || m.owner || '' hold no value, so they can neither breach nor improve: '' || group_concat(m.metric_key, '', '') || ''. Lever: build or repair the producer named in each metric''''s source_of_truth in metric_registry (never write a value by hand). Closes on its own when every one of them holds a value (probe on metric_improvement_now).'', ''management-personas'', ''measurement'', ''medium'', ''open'', CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000, CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000 FROM metric_improvement_now m WHERE m.verdict = ''unmeasured'' AND m.bp26 = 0 AND COALESCE((SELECT value FROM ops_config WHERE key = ''persona_actions''), ''on'') <> ''off'' GROUP BY m.owner HAVING NOT EXISTS (SELECT 1 FROM agent_issues b WHERE b.status = ''open'' AND b.title = ''METRIC-UNMEASURED-1: '' || m.owner || '' has metrics with no value'')"}')), '$.steps[#]', json('{"type": "sql", "name": "mi-unmeasured-map", "db": "AUDIT", "sql": "INSERT OR IGNORE INTO issue_project_map (issue_id, project_code, program_code, kind, updated_at) SELECT a.id, ''W.'' || m.program_code, m.program_code, ''fix'', datetime(''now'') FROM agent_issues a JOIN metric_improvement_now m ON a.title = ''METRIC-UNMEASURED-1: '' || m.owner || '' has metrics with no value'' WHERE a.status = ''open''"}')), '$.steps[#]', json('{"type": "sql", "name": "mi-unmeasured-probe", "db": "AUDIT", "sql": "UPDATE remediation_contracts SET verify_probe = (SELECT ''SELECT ''''0'''' AS expected, CAST((SELECT COUNT(*) FROM metric_improvement_now WHERE verdict = ''''unmeasured'''' AND bp26 = 0 AND owner = '''''' || substr(a.title, 22, length(a.title) - 21 - 26) || '''''') AS TEXT) AS observed'' FROM agent_issues a WHERE a.id = remediation_contracts.issue_id), verify_transport = ''d1-query'' WHERE class IN (SELECT ''issue-'' || a.id FROM agent_issues a WHERE a.status = ''open'' AND a.title LIKE ''METRIC-UNMEASURED-1: % has metrics with no value'') AND COALESCE(verify_probe, '''') NOT LIKE ''%metric_improvement_now%''"}')), '$.steps[#]', json('{"type": "sql", "name": "mi-unmeasured-close-evidence", "db": "AUDIT", "sql": "INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT id, ''measured'', ''triaged'', ''management-personas'', datetime(''now''), ''every metric trigger of this owner holds a value (metric_improvement_now at '' || strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'') || '')'' FROM (SELECT a.id FROM agent_issues a WHERE a.status = ''open'' AND a.title LIKE ''METRIC-UNMEASURED-1: % has metrics with no value'' AND NOT EXISTS (SELECT 1 FROM metric_improvement_now m WHERE m.verdict = ''unmeasured'' AND m.bp26 = 0 AND a.title = ''METRIC-UNMEASURED-1: '' || m.owner || '' has metrics with no value'')) WHERE 1 ON CONFLICT(issue_id) DO UPDATE SET close_evidence = excluded.close_evidence"}')), '$.steps[#]', json('{"type": "sql", "name": "mi-unmeasured-close-log", "db": "AUDIT", "sql": "INSERT INTO persona_actions (persona_key, kind, issue_id, from_value, to_value, evidence) SELECT ''portfolio-manager'', ''close'', id, ''open'', ''closed'', ''every metric of the owner holds a value'' FROM (SELECT a.id FROM agent_issues a WHERE a.status = ''open'' AND a.title LIKE ''METRIC-UNMEASURED-1: % has metrics with no value'' AND NOT EXISTS (SELECT 1 FROM metric_improvement_now m WHERE m.verdict = ''unmeasured'' AND m.bp26 = 0 AND a.title = ''METRIC-UNMEASURED-1: '' || m.owner || '' has metrics with no value''))"}')), '$.steps[#]', json('{"type": "sql", "name": "mi-unmeasured-close", "db": "AUDIT", "sql": "UPDATE agent_issues SET status = ''closed'', close_channel = ''auto:management-personas'', updated_at = CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000 WHERE id IN (SELECT a.id FROM agent_issues a WHERE a.status = ''open'' AND a.title LIKE ''METRIC-UNMEASURED-1: % has metrics with no value'' AND NOT EXISTS (SELECT 1 FROM metric_improvement_now m WHERE m.verdict = ''unmeasured'' AND m.bp26 = 0 AND a.title = ''METRIC-UNMEASURED-1: '' || m.owner || '' has metrics with no value''))"}')), '$.steps[#]', json('{"type": "sql", "name": "lever-request", "db": "AUDIT", "sql": "INSERT INTO cf_agent_requests (requester, kind, prompt, instance, priority) SELECT ''program-manager:'' || m.program_code, ''run'', ''You are the program manager of '' || m.program_code || '' in the QNFO fleet. Metric '' || m.metric_key || '' (trigger #'' || m.trigger_id || '', breach when '' || m.operator || '' '' || m.threshold || '') reads '' || COALESCE(m.val, ''?'') || '' now and '' || COALESCE(m.val_7d, ''?'') || '' seven days ago, so its remedy has not moved it (METRIC-CLOSED-LOOP-1: a remedy that did not move its metric in 7 days is replaced, not repeated). Its open issue is #'' || m.open_issue_id || ''. The current lever: '' || substr(COALESCE((SELECT a.action FROM analytics_metric_triggers a WHERE a.id = m.trigger_id), ''''), 1, 1200) || char(10) || ''Read the metric''''s formula and source_of_truth in qnfo-audit.metric_registry, the producer''''s code in the qnfo-workers repository and the issue. Answer in under 250 words: why the metric is not moving (the producer or root cause), and a different lever: a code-task line (repo=qnfo-workers path=<file>) with a code-anchor (verbatim text that occurs once in that file) and the exact edit, or a corrected target with the evidence that the current one is wrong.'', ''lever-'' || m.trigger_id || ''-'' || strftime(''%Y%m%d%H%M'', ''now''), ''medium'' FROM metric_improvement_now m WHERE m.verdict IN (''breach-worsening'', ''breach-flat'') AND m.open_issue_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM cf_agent_requests r WHERE r.instance LIKE ''lever-'' || m.trigger_id || ''-%'' AND (r.status IN (''queued'', ''running'') OR (r.created_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-3 days'') AND COALESCE(r.result, '''') NOT LIKE ''(the model returned no text)%'' AND r.status = ''done''))) AND COALESCE((SELECT value FROM ops_config WHERE key = ''persona_actions''), ''on'') <> ''off'' ORDER BY m.priority, CASE m.verdict WHEN ''breach-worsening'' THEN 0 ELSE 1 END, m.trigger_id LIMIT 5"}')), '$.steps[#]', json('{"type": "sql", "name": "lever-log", "db": "AUDIT", "sql": "INSERT INTO persona_actions (persona_key, kind, issue_id, from_value, to_value, evidence) SELECT r.requester, ''lever-review'', m.open_issue_id, r.instance, ''requested'', ''cf_agent_requests #'' || r.id || '': Cloudflare agent asked to replace the lever of '' || m.metric_key || '' ('' || m.verdict || '', '' || COALESCE(m.val_7d, ''?'') || '' -> '' || COALESCE(m.val, ''?'') || '')'' FROM cf_agent_requests r JOIN metric_improvement_now m ON r.instance LIKE ''lever-'' || m.trigger_id || ''-%'' WHERE r.status = ''queued'' AND NOT EXISTS (SELECT 1 FROM persona_actions p WHERE p.kind = ''lever-review'' AND p.from_value = r.instance)"}')), '$.steps[#]', json('{"type": "sql", "name": "lever-report", "db": "AUDIT", "sql": "UPDATE agent_issues SET description = COALESCE(description, '''') || char(10) || char(10) || ''Lever review by the Cloudflare agent ('' || (SELECT x.from_value FROM persona_actions x WHERE x.id = (SELECT MIN(p.id) FROM persona_actions p JOIN cf_agent_requests r ON r.instance = p.from_value WHERE p.kind = ''lever-review'' AND p.to_value = ''requested'' AND p.issue_id = agent_issues.id AND r.status IN (''done'', ''failed'', ''error'') AND COALESCE(r.result, '''') NOT LIKE ''(the model returned no text)%'' AND COALESCE(r.result, r.error, '''') <> '''')) || '', the metric did not improve in 7 days): '' || substr((SELECT COALESCE(r.result, r.error, '''') FROM cf_agent_requests r WHERE r.instance = (SELECT x.from_value FROM persona_actions x WHERE x.id = (SELECT MIN(p.id) FROM persona_actions p JOIN cf_agent_requests r ON r.instance = p.from_value WHERE p.kind = ''lever-review'' AND p.to_value = ''requested'' AND p.issue_id = agent_issues.id AND r.status IN (''done'', ''failed'', ''error'') AND COALESCE(r.result, '''') NOT LIKE ''(the model returned no text)%'' AND COALESCE(r.result, r.error, '''') <> '''')) ORDER BY r.id DESC LIMIT 1), 1, 2000), updated_at = CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000 WHERE status = ''open'' AND (SELECT MIN(p.id) FROM persona_actions p JOIN cf_agent_requests r ON r.instance = p.from_value WHERE p.kind = ''lever-review'' AND p.to_value = ''requested'' AND p.issue_id = agent_issues.id AND r.status IN (''done'', ''failed'', ''error'') AND COALESCE(r.result, '''') NOT LIKE ''(the model returned no text)%'' AND COALESCE(r.result, r.error, '''') <> '''') IS NOT NULL"}')), '$.steps[#]', json('{"type": "sql", "name": "lever-mark", "db": "AUDIT", "sql": "UPDATE persona_actions SET to_value = CASE WHEN EXISTS (SELECT 1 FROM cf_agent_requests r WHERE r.instance = persona_actions.from_value AND r.status IN (''done'', ''failed'', ''error'') AND (COALESCE(r.result, '''') LIKE ''(the model returned no text)%'' OR COALESCE(r.result, r.error, '''') = '''')) THEN ''empty'' ELSE ''reported'' END WHERE kind = ''lever-review'' AND to_value = ''requested'' AND (id IN (SELECT MIN(p.id) FROM persona_actions p JOIN cf_agent_requests r ON r.instance = p.from_value WHERE p.kind = ''lever-review'' AND p.to_value = ''requested'' AND r.status IN (''done'', ''failed'', ''error'') AND COALESCE(r.result, '''') NOT LIKE ''(the model returned no text)%'' AND COALESCE(r.result, r.error, '''') <> '''' GROUP BY p.issue_id) OR EXISTS (SELECT 1 FROM cf_agent_requests r WHERE r.instance = persona_actions.from_value AND r.status IN (''done'', ''failed'', ''error'') AND (COALESCE(r.result, '''') LIKE ''(the model returned no text)%'' OR COALESCE(r.result, r.error, '''') = '''')))"}')), '$.steps[#]', json('{"type": "sql", "name": "brief-audit", "db": "AUDIT", "sql": "UPDATE persona_briefs SET summary = summary || '' Metric audit ('' || (SELECT triggers FROM metric_improvement_trend ORDER BY tick DESC LIMIT 1) || '' triggers): '' || (SELECT on_target || '' on target, '' || improving || '' breaches improving, '' || flat || '' flat, '' || worsening || '' worse than 7 days ago, '' || new_breach || '' new, '' || unmeasured || '' unmeasured'' FROM metric_improvement_trend ORDER BY tick DESC LIMIT 1) || ''; quality '' || COALESCE((SELECT last_value FROM metric_registry WHERE metric = ''fleet_quality_change_7d''), ''?'') || '' points over 7 days. Worst: '' || COALESCE((SELECT group_concat(metric_key, '', '') FROM (SELECT metric_key FROM metric_improvement_now WHERE verdict = ''breach-worsening'' ORDER BY priority, trigger_id LIMIT 3)), ''none'') || ''.'' WHERE persona_key = ''portfolio-manager'' AND tick = (SELECT MAX(tick) FROM portfolio_allocations) AND summary NOT LIKE ''%Metric audit (%''"}')),
  version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
WHERE id = 'management-personas' AND instr(definition, '"mi-snapshot"') = 0;

INSERT OR IGNORE INTO metric_registry (metric, layer, kind, formula, source_of_truth, target, owner, disposition_actor, refresh_cadence, state) VALUES
  ('metrics_worsening_7d', 'operational', 'target',
   'enabled metric triggers in breach whose value is worse than, or equal to, its value 7 days ago (metric_improvement_now verdict breach-worsening or breach-flat)',
   'qnfo-audit.metric_improvement_now (MANAGEMENT-PERSONAS-5), written hourly by fleet_tasks management-personas', '0', 'qnfo-fleet-control', 'agent:management-personas', 'hourly', 'PENDING'),
  ('metrics_unmeasured', 'operational', 'guard',
   'enabled metric triggers that hold no value (metric_improvement_now verdict unmeasured). Trigger exemption: BP26 metrics have the bp26_metrics_unmeasured trigger and every other owner gets a METRIC-UNMEASURED-1 issue from the managers, which is the action a trigger would take',
   'qnfo-audit.metric_improvement_now (MANAGEMENT-PERSONAS-5), written hourly by fleet_tasks management-personas', '0', 'qnfo-fleet-control', 'agent:management-personas', 'hourly', 'PENDING'),
  ('fleet_quality_change_7d', 'operational', 'target',
   'change in points of the quality index (share of measured metric triggers on target, metric_improvement_trend) against the oldest hourly row in the last 7 days; the fleet''s daily target is to raise it',
   'qnfo-audit.metric_improvement_trend (MANAGEMENT-PERSONAS-5), written hourly by fleet_tasks management-personas', '>= 0', 'qnfo-fleet-control', 'agent:management-personas', 'hourly', 'PENDING');

INSERT INTO analytics_metric_triggers (metric_key, title, source_table, operator, threshold, priority, action, owner, queue_target, cooldown_hours, enabled, notes)
SELECT 'metrics_worsening_7d', 'Metrics in breach that have not improved in 7 days', 'registry', 'gt', 10, 2,
  'Pillar autonomy (QUALITY-IMPROVEMENT-AUDIT-1). List them: SELECT metric_key, verdict, val_7d, val, open_issue_id, has_code_task FROM metric_improvement_now WHERE verdict IN (''breach-worsening'', ''breach-flat'') ORDER BY priority. Lever: the managers ask the Cloudflare agent for a replacement lever on each (persona_actions kind lever-review, answer on the metric''s issue); the code loop and the owning loops act on those levers. A lever that has been reviewed twice without movement is a code-task for its producer. Definition of done: metrics_worsening_7d <= 10, then 0.',
  'program-manager:QNFO.OPS', 'agent_issues', 2, 1, 'QUALITY-IMPROVEMENT-AUDIT-1 (migrations/2026-10-26-management-personas-5.sql)'
WHERE NOT EXISTS (SELECT 1 FROM analytics_metric_triggers WHERE metric_key = 'metrics_worsening_7d');

INSERT INTO analytics_metric_triggers (metric_key, title, source_table, operator, threshold, priority, action, owner, queue_target, cooldown_hours, enabled, notes)
SELECT 'fleet_quality_change_7d', 'Fleet quality index fell over 7 days', 'registry', 'lt', -2, 2,
  'Pillar autonomy (QUALITY-IMPROVEMENT-AUDIT-1). Read which programs fell: SELECT * FROM v_metric_improvement_by_program ORDER BY quality_index; and the newest breaches: SELECT metric_key, verdict FROM metric_improvement_now WHERE verdict IN (''breach-new'', ''breach-worsening'') ORDER BY priority. Lever: the portfolio manager escalates the program whose index fell (focus raised by half, MANAGEMENT-PERSONAS-3) and its lever reviews run first. Definition of done: fleet_quality_change_7d >= 0.',
